export const quizQuestionBanks={'6-8':easy,'9-11':middle,'12-14':advanced};
export function quizFor(id,age,base){const b=base[id];if(!b)return null;return {...b,questions:age==='6-8'?easy[id]:age==='12-14'?advanced[id]:middle[id]};}
export function shuffleQuestion(question,random=Math.random){const rows=question.options.map((text,index)=>({text,index}));for(let i=rows.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[rows[i],rows[j]]=[rows[j],rows[i]];}return {...question,options:rows.map(x=>x.text),correct:rows.findIndex(x=>x.index===question.correct)};}
